pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;
    uint prev;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _test(uint256 newAmount) internal {
        try c.currentBetLimit() returns (uint256 __r) { prev = __r; } catch { return; }
        try c.AdjustBetAmounts(newAmount) {} catch { return; }
        assertTrue(c.currentBetLimit() == newAmount);
    }

    function testFuzz_test(uint256 newAmount) public {
        _test(newAmount);
    }

    receive() external payable {}
}
